//! Differential for `BigFloat::bi`, `ai_prime`, `bi_prime`. MPFR
//! has no `Bi`/`Ai′`/`Bi′`, so the oracle is a checked-in
//! authoritative reference table (generated by `mpmath`
//! `airybi/airyai(.,1)/airybi(.,1)` at 80 digits — the primary-source
//! recipe used for the slice-6m references; treated as a fact)
//! parsed by the bit-exact decimal parser, plus the Wronskian
//! cross-tie `Ai·Bi′ − Ai′·Bi = 1/π` (DLMF 9.2.7) and a
//! high-precision self-consistency sweep.
//!
//! Tolerance `p − 2` bits (the `differential_si` posture; pfloat has
//! no Ziv correct-rounding yet). Precisions capped at 256: each
//! evaluation drives the gamma kernel twice, so p=1024 over the full
//! table is impractical here — the p=1024 path is pinned by the
//! airy-module unit tests (boundary constants and the Wronskian to
//! ~176 bits at p=200).

#![cfg(all(unix, feature = "differential-mpfr"))]

mod differential;

use differential::{next_i64_in, sweep_size, TRANSCENDENTAL_PRECISIONS};
use pfloat::{BigFloat, RoundingMode};

fn close_within(a: &BigFloat, b: &BigFloat, bits: u32) -> bool {
    let (diff, _) = a.sub(b, RoundingMode::NearestEven);
    let abs = diff.abs();
    if abs.is_zero() {
        return true;
    }
    let p = a.precision().max(b.precision());
    let two = BigFloat::try_from_i64_exact(2, p).unwrap();
    let mut bound = b.abs();
    if bound.is_zero() {
        bound = BigFloat::try_from_i64_exact(1, p).unwrap();
    }
    for _ in 0..bits {
        bound = bound.div(&two, RoundingMode::NearestEven).0;
    }
    matches!(
        abs.partial_cmp(&bound).0,
        Some(core::cmp::Ordering::Less | core::cmp::Ordering::Equal)
    )
}

fn at(num: i64, den: i64, p: u32) -> BigFloat {
    let n = BigFloat::try_from_i64_exact(num, p).unwrap();
    if den == 1 {
        n
    } else {
        n.div(
            &BigFloat::try_from_i64_exact(den, p).unwrap(),
            RoundingMode::NearestEven,
        )
        .0
    }
}

