#[test]
fn bi_family_matches_authoritative_table() {
    for &p in TRANSCENDENTAL_PRECISIONS.iter().filter(|&&p| p <= 256) {
        for &(num, den, bi_s, aip_s, bip_s) in BI_TABLE {
            let x = at(num, den, p);
            let (bi, _) = x.bi(RoundingMode::NearestEven);
            let (aip, _) = x.ai_prime(RoundingMode::NearestEven);
            let (bip, _) = x.bi_prime(RoundingMode::NearestEven);
            for (got, refstr, name) in [
                (&bi, bi_s, "Bi"),
                (&aip, aip_s, "Ai'"),
                (&bip, bip_s, "Bi'"),
            ] {
                let want = BigFloat::parse_str(refstr, p, RoundingMode::NearestEven)
                    .unwrap()
                    .0;
                assert!(
                    close_within(got, &want, p - 2),
                    "{name}({num}/{den}) at p={p}: got {got}, want {want}"
                );
            }
        }
    }
}

#[test]
fn wronskian_identity_holds() {
    // Ai·Bi′ − Ai′·Bi = 1/π for every x (DLMF 9.2.7): the primary
    // cross-tie binding Ai′/Bi′, which have no independent oracle.
    // 1/π to 85 digits (mpmath; treated as a fact), the airy-module
    // unit-test approach — the crate exposes no public π accessor.
    const INV_PI: &str =
        "0.3183098861837906715377675267450287240689192914809128974953346881177935952684530701802";
    for &p in TRANSCENDENTAL_PRECISIONS.iter().filter(|&&p| p <= 256) {
        let inv_pi = BigFloat::parse_str(INV_PI, p, RoundingMode::NearestEven)
            .unwrap()
            .0;
        for &(num, den, _, _, _) in BI_TABLE {
            let x = at(num, den, p);
            let (ai, _) = x.ai(RoundingMode::NearestEven);
            let (bi, _) = x.bi(RoundingMode::NearestEven);
            let (aip, _) = x.ai_prime(RoundingMode::NearestEven);
            let (bip, _) = x.bi_prime(RoundingMode::NearestEven);
            let (t1, _) = ai.mul(&bip, RoundingMode::NearestEven);
            let (t2, _) = aip.mul(&bi, RoundingMode::NearestEven);
            let (w, _) = t1.sub(&t2, RoundingMode::NearestEven);
            assert!(
                close_within(&w, &inv_pi, p - 8),
                "Wronskian at {num}/{den}, p={p}: got {w}"
            );
        }
    }
}

#[test]
fn bi_self_consistent() {
    // Bi at p must agree with Bi at p+64 (rounded to p) to p−8 bits:
    // catches regime/algorithm bugs without an external oracle.
    let mut state: u64 = u64::from_le_bytes(*b"pf6nbisc");
    for &p in &[53u32, 113] {
        for _ in 0..sweep_size().min(20) {
            let a = next_i64_in(&mut state, -8, 8);
            let lo = {
                let (r, _) = at(a, 1, p).bi(RoundingMode::NearestEven);
                r
            };
            let hi = {
                let (r, _) = at(a, 1, p + 64).bi(RoundingMode::NearestEven);
                r.round_to_precision(p, RoundingMode::NearestEven)
                    .unwrap()
                    .0
            };
            assert!(
                close_within(&lo, &hi, p - 8),
                "Bi({a}) self-consistency at p={p}: lo={lo} hi={hi}"
            );
        }
    }
}
